      '【正解】この選択肢は正しいです。共同不法行為者の一人が損害賠償をした場合、自己の負担部分を超えた部分については他の共同不法行為者に求償することができます（民法442条等）。求償額は各加害者の過失割合に応じた負担部分の算定に基づきます。',
